/**
 * Public project database schema. Generated by scripts/build-db.py from
 *   data/sources/project-sources.json   (archive → unique buildings)
 *   data/geo/*.json                     (geolocation research, evidence)
 *   data/curation/projects.json         (verified material data, texts, model status)
 * Never hand-edit src/data/projects.json — edit the inputs and run `npm run db`.
 */
export type Lang = 'ro' | 'hu' | 'en'
export type I18nText = Partial<Record<Lang, string>>

export type Confidence = 'VERIFIED' | 'PROBABLE' | 'UNRESOLVED'
export type Accuracy = 'building' | 'site' | 'street' | 'locality'
export type Metal = 'copper' | 'titanium-zinc' | 'aluminium' | 'brass'
export type Category =
  | 'church'
  | 'monastery'
  | 'castle'
  | 'historic'
  | 'museum'
  | 'cultural'
  | 'library'
  | 'education'
  | 'stadium'
  | 'commercial'
  | 'healthcare'
  | 'residential'
  | 'parking'
  | 'refuge'

/** A = premium detailed, B = recognisable, C = preliminary, D = location & photos only. */
export type ModelTier = 'A' | 'B' | 'C' | 'D'
export type ModelStatus =
  | 'existing-verified'
  | 'detailed'
  | 'preview'
  | 'reference-limited'
  | 'in-development'
  | 'pending-photos'
  | 'none'

export interface Photo {
  file: string
  w: number
  h: number
  kind: 'photo' | 'drone'
}

export interface Project {
  id: string
  name: string
  nameHu?: string
  nameEn?: string
  city: string
  cityHu?: string
  county: string
  country: string
  lat: number
  lon: number
  geographicAccuracy: Accuracy
  identificationConfidence: Confidence
  /** Real-world azimuth (deg, clockwise from north) of the model's local +X axis. */
  bearingDeg: number
  bearingSource?: string
  category: Category
  metals: Metal[]
  /** Product / finish names as supplied (e.g. "elZinc Slate", "KME copper"). Not translated. */
  products: string[]
  finish?: I18nText
  application?: I18nText
  /** COLOR METAL's verified contribution (company texts / internal register). */
  contribution?: I18nText
  description?: I18nText
  photos: Photo[]
  /** published = public gallery; unapproved = archive photos awaiting publication approval;
   *  reference = modelled from public reference photographs (not published); none = no photos */
  photoStatus: 'published' | 'unapproved' | 'reference' | 'none'
  cover?: string
  model: {
    tier: ModelTier
    status: ModelStatus
    /** Present when an interactive model module exists (src/models/...). */
    module?: string
    note?: I18nText
  }
  sourceUrls: string[]
  /** OSM building outline, local metres [east, north] relative to (lat, lon) — QA overlay */
  footprint?: [number, number][]
  lastUpdated: string
}

export interface Database {
  generated: string
  projects: Project[]
}
